import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { codexTurnRunning, pickCodexWakes, readRolloutForTurnCheck, } from "./codexExperimentWaker.js";
const URL = "https://bitfab.ai/experiments/e";
function running(overrides) {
    return {
        id: "run-1",
        name: "Shorter prompt",
        finished: 3,
        total: 10,
        url: URL,
        stalled: false,
        errored: null,
        ...overrides,
    };
}
function finished(overrides) {
    return {
        id: "done-1",
        name: "Shorter prompt",
        status: "completed",
        url: URL,
        announce: true,
        finished: 10,
        errored: 2,
        total: 10,
        ...overrides,
    };
}
describe("pickCodexWakes", () => {
    it("wakes once for a stalled experiment", () => {
        const handled = new Set();
        const snapshot = { running: [running({ stalled: true })], finished: [] };
        const first = pickCodexWakes(snapshot, handled, true);
        const second = pickCodexWakes(snapshot, handled, false);
        expect(first).toHaveLength(1);
        expect(first[0].text).toContain("has replayed nothing new for 10 minutes");
        expect(second).toEqual([]);
    });
    it("wakes for the finish of an experiment it already woke for a stall", () => {
        const handled = new Set();
        pickCodexWakes({ running: [running({ id: "done-1", stalled: true })], finished: [] }, handled, false);
        const wakes = pickCodexWakes({ running: [], finished: [finished({})] }, handled, false);
        expect(wakes).toHaveLength(1);
        expect(wakes[0].text).toContain("(done-1) finished: complete");
    });
    it("does not wake for an experiment that is still making progress", () => {
        expect(pickCodexWakes({ running: [running({})], finished: [] }, new Set(), false)).toEqual([]);
    });
    it("wakes for a finish while no turn is running", () => {
        const wakes = pickCodexWakes({ running: [], finished: [finished({})] }, new Set(), false);
        expect(wakes).toHaveLength(1);
        expect(wakes[0].text).toContain("Bitfab experiment Shorter prompt (done-1) finished: complete, 10/10 replayed, 2 errored, https://bitfab.ai/experiments/e");
    });
    it("stays quiet for a finish during a turn, and does not wake for it later", () => {
        const handled = new Set();
        const snapshot = { running: [], finished: [finished({})] };
        expect(pickCodexWakes(snapshot, handled, true)).toEqual([]);
        expect(pickCodexWakes(snapshot, handled, false)).toEqual([]);
    });
    it("stays quiet for experiments that had already finished when the watch began", () => {
        expect(pickCodexWakes({ running: [], finished: [finished({ announce: false })] }, new Set(), false)).toEqual([]);
    });
    it("leaves the counts out of a failed experiment", () => {
        const [wake] = pickCodexWakes({ running: [], finished: [finished({ status: "failed" })] }, new Set(), false);
        expect(wake.text).toContain("finished: failed, https://");
    });
});
describe("codexTurnRunning", () => {
    const started = '{"type":"event_msg","payload":{"type":"task_started"}}';
    const ended = '{"type":"event_msg","payload":{"type":"task_complete"}}';
    it("is running after a turn starts", () => {
        expect(codexTurnRunning(`${ended}\n${started}\n`)).toBe(true);
    });
    it("is idle after the turn completes", () => {
        expect(codexTurnRunning(`${started}\n${ended}\n`)).toBe(false);
    });
    it("is idle before any turn", () => {
        expect(codexTurnRunning("")).toBe(false);
    });
    it("reads the whole log when a long turn pushed its start out of the tail", () => {
        const dir = fs.mkdtempSync(path.join(os.tmpdir(), "codex-rollout-"));
        const file = path.join(dir, "rollout.jsonl");
        const filler = '{"type":"response_item","payload":"x"}\n'.repeat(10_000);
        fs.writeFileSync(file, `${ended}\n${started}\n${filler}`);
        expect(codexTurnRunning(readRolloutForTurnCheck(file))).toBe(true);
        fs.rmSync(dir, { recursive: true, force: true });
    });
});
